@njit(cache=True)
def _find_rho_theta(sorted_y):
    n = sorted_y.shape[0]
    cumsum = 0.0
    rho = 0
    theta = 0.0
    for i in range(n):
        cumsum += sorted_y[i]
        t = (cumsum - 1.0) / (i + 1)
        if sorted_y[i] > t:
            rho = i
            theta = t
    return theta

class Solver:
    def __init__(self):
        _find_rho_theta(np.array([1.2, 1.0]))

    def solve(self, problem, **kwargs):
        y = np.asarray(problem["y"], dtype=np.float64)
        n = y.shape[0]
        sorted_y = np.sort(y)[::-1]
        theta = _find_rho_theta(sorted_y)
        x = np.maximum(y - theta, 0.0)
        return {"solution": x}

